websocket_info({?REPLY_TAG, MonitorRef, Outcome}, #{in_flight := InFlight} = State) ->
    case maps:take(MonitorRef, InFlight) of
        {_Id, Rest} ->
            erlang:demonitor(MonitorRef, [flush]),
            {frames(Outcome), State#{in_flight := Rest}};
        error ->
            {[], State}
    end;
websocket_info({'DOWN', MonitorRef, process, _Pid, Reason}, #{in_flight := InFlight} = State) ->
    %% The dispatch process died without reporting. Everything a handler can
    %% raise is already contained, so this means the process was killed from
    %% outside; the client is still owed an answer.
    case maps:take(MonitorRef, InFlight) of
        {Id, Rest} ->
            ?LOG_ERROR("json_rpc: WebSocket dispatch died: ~p", [Reason]),
            Body = json_rpc_transport:error_body(Id, json_rpc_error:internal_error()),
            {[{text, Body}], State#{in_flight := Rest}};
        error ->
            {[], State}
    end;

